declare(strict_types=1);
function view_gallery(array $images): void {
    if(!$images){echo '<div class="empty"><p>No approved photographs are available for this project yet.</p></div>';return;}
    echo '<div class="evidence-carousel-header"><p class="small muted">Browse project photographs. Open any image for full-size viewing, zoom and pan.</p><div class="evidence-carousel-actions"><button type="button" class="btn btn-small btn-outline gallery-scroll-back" aria-label="Previous photographs">‹</button><button type="button" class="btn btn-small btn-outline gallery-scroll-next" aria-label="Next photographs">›</button></div></div>';
    echo '<div class="evidence-track" id="projectEvidenceCarousel" aria-label="Project photographic evidence">';
    foreach($images as $image) echo '<article class="evidence-card"><button type="button" class="evidence-open" data-gallery-open data-title="'.e($image['activity_title']).'" data-date="'.e($image['evidence_date']).'" aria-label="View photo for '.e($image['activity_title']).'"><img src="image.php?id='.(int)$image['id'].'" alt="Evidence for '.e($image['activity_title']).'" loading="lazy"><span class="evidence-zoom-hint">⌕ View and zoom</span></button><div><h3>'.e($image['activity_title']).'</h3><p>'.e($image['evidence_date']).'</p>'.status_badge($image['review_status']).'</div></article>';
    echo '</div><dialog class="evidence-viewer" id="evidenceViewer" aria-label="Full-size project photographs"><div class="evidence-viewer-top"><strong id="evidenceViewerTitle">Site photograph</strong><button type="button" class="evidence-viewer-control" data-gallery-close aria-label="Close image viewer">✕</button></div><div class="evidence-viewer-main"><button type="button" class="evidence-viewer-arrow" data-gallery-prev aria-label="Previous image">‹</button><div class="evidence-image-area" id="evidenceImageArea"><img id="evidenceViewerImage" alt="Full-size site photograph" draggable="false"></div><button type="button" class="evidence-viewer-arrow" data-gallery-next aria-label="Next image">›</button></div><div class="evidence-viewer-bottom"><span id="evidenceViewerCount" aria-live="polite"></span><div class="evidence-zoom-controls"><button type="button" data-zoom-out aria-label="Zoom out">−</button><button type="button" data-zoom-reset>Reset (100%)</button><button type="button" data-zoom-in aria-label="Zoom in">+</button></div><span id="evidenceViewerCaption"></span></div></dialog>';
}
function finance_cards(array $f): void {
    echo '<div class="finance-grid"><div class="metric-card"><span>Approved project budget</span><strong>'.money($f['budget_total']).'</strong></div><div class="metric-card"><span>Funding received</span><strong>'.money($f['funding']).'</strong></div><div class="metric-card"><span>Recorded expenditure</span><strong>'.money($f['expenses']).'</strong></div><div class="metric-card"><span>Budget remaining</span><strong>'.money($f['remaining']).'</strong></div><div class="metric-card"><span>Cash balance</span><strong>'.money($f['cash_balance']).'</strong></div><div class="metric-card"><span>Budget utilised</span><strong>'.number_format((float)$f['utilization'],1).'%</strong>'.progress_bar((int)min(100,$f['utilization'])).'</div></div>';
}
function field(string $name,string $label,string $value='',string $type='text',string $extra=''): void {
    echo '<div class="field"><label for="'.e($name).'">'.e($label).'</label><input id="'.e($name).'" name="'.e($name).'" type="'.e($type).'" value="'.e($value).'" '.$extra.'></div>';
}
